        "{\"@context\":\"https://schema.org\",\"@type\":\"FAQPage\",\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"\u4ec0\u9ebc\u662fTurboScribe\uff1f\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"\\u003Cp>TurboScribe \u662f\u4e00\u9805\u4eba\u5de5\u667a\u6167\u8f49\u9304\u670d\u52d9\uff0c\u63d0\u4f9b\u7121\u9650\u97f3\u8a0a\u548c\u8996\u983b\u8f49\u9304\u3002TurboScribe \u4ee5\u6975\u9ad8\u7684\u6e96\u78ba\u5ea6\u5c07\u97f3\u8a0a\u548c\u8996\u983b\u6587\u4ef6\u8f49\u63db\u70ba 98 \u7a2e\u4ee5\u4e0a\u7684\u8a9e\u8a00\u6587\u5b57\u3002\\u003C/p>\\n\"}},{\"@type\":\"Question\",\"name\":\"\u591a\u5c11\u9322\uff1f\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"\\u003Cp>TurboScribe \u7121\u9650\u8cbb\u7528\u70ba $10/\u6708\uff08\u6bcf\u5e74\u6536\u8cbb\uff09\u6216 $20/\u6708\uff08\u6bcf\u6708\u6536\u8cbb\uff09\u3002\\u003C/p>\\n\"}},{\"@type\":\"Question\",\"name\":\"TurboScribe \u771f\u7684\u7121\u9650\u5236\u55ce\uff1f\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"\\u003Cp>\u662f\u7684\uff01TurboScribe \u78ba\u5be6\u662f\u7121\u9650\u7684\u3002\\u003C/p>\\n\\u003Cp>\u7e3d\u9ad4\u4f7f\u7528\u91cf\u6c92\u6709\u4e0a\u9650\uff0c\u5ba2\u6236\u7d93\u5e38\u6bcf\u6708\u8f49\u9304\\u003Cem>\u6578\u767e\\u003C/em>\u5c0f\u6642\u3002\u552f\u4e00\u7684\u898f\u5247\u662f\u60a8\u4e0d\u80fd\u8207\u4ed6\u4eba\u5171\u4eab\u60a8\u7684\u767b\u5165/\u5e33\u6236\u3002\\u003C/p>\\n\"}},{\"@type\":\"Question\",\"name\":\"\u6211\u53ef\u4ee5\u4e0a\u50b3\u5927\u6587\u4ef6\u55ce\uff1f\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"\\u003Cp>\u662f\u7684\uff01TurboScribe \u80fd\u5920\u8655\u7406\u5927\u91cf\u4e0a\u50b3\u3002\u6bcf\u500b\u4e0a\u50b3\u7684\u6587\u4ef6\u53ef\u4ee5\u9577\u905410\u5c0f\u6642\uff0c\u5927\u5c0f\u9054\u52305GB\u3002\u7121\u9650\u6703\u54e1\u4e00\u6b21\u53ef\u4ee5\u4e0a\u50b3\u6700\u591a50\u500b\u6587\u4ef6\u3002\\u003C/p>\\n\"}},{\"@type\":\"Question\",\"name\":\"TurboScribe \u5b89\u5168\u55ce\uff1f\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"\\u003Cp>\u662f\u7684\u3002\u60a8\u7684\u8f49\u9304\u6587\u672c\u3001\u4e0a\u50b3\u7684\u6a94\u6848\u548c\u5e33\u6236\u8cc7\u8a0a\u90fd\u7d93\u904e\u52a0\u5bc6\uff0c\u53ea\u6709\u60a8\u53ef\u4ee5\u5b58\u53d6\u3002\u60a8\u53ef\u4ee5\u96a8\u6642\u522a\u9664\u5b83\u5011\u3002\u6211\u5011\u4f7f\u7528 Stripe \u4f86\u5b89\u5168\u8655\u7406\u4ed8\u6b3e\uff0c\u4e14\u4e0d\u6703\u5132\u5b58\u60a8\u7684\u4fe1\u7528\u5361\u865f\u78bc\u3002\\u003C/p>\\n\\u003Cp>\u5982\u9700\u66f4\u591a\u5b89\u5168\u548c\u96b1\u79c1\u8cc7\u8a0a\uff0c\u8acb\u95b1\u8b80\u6211\u5011\u7684\\u003Ca href=\\\"https://turboscribe.ai/zh-TW/blog/security-and-privacy-faq\\\">\u5b89\u5168\u548c\u96b1\u79c1\u5e38\u898b\u554f\u984c\\u003C/a>\u3002\\u003C/p>\\n\"}},{\"@type\":\"Question\",\"name\":\"\u60a8\u652f\u6301\u54ea\u4e9b\u97f3\u8a0a/\u8996\u983b\u683c\u5f0f\uff1f\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"\\u003Cp>TurboScribe \u652f\u63f4\u7d55\u5927\u591a\u6578\u5e38\u898b\u7684\u97f3\u8a0a\u548c\u8996\u983b\u683c\u5f0f\uff0c\u5305\u62ec MP3\u3001M4A\u3001MP4\u3001MOV\u3001AAC\u3001WAV\u3001OGG\u3001OPUS\u3001MPEG\u3001WMA\u3001WMV\u3001AVI\u3001FLAC\u3001AIFF\u3001ALAC\u30013GP\u3001MKV\u3001WEBM\u3001VOB\u3001RMVB\u3001MTS\u3001TS\u3001QuickTime \u548c DivX\u3002\\u003C/p>\\n\"}},{\"@type\":\"Question\",\"name\":\"\u6211\u53ef\u4ee5\u532f\u51fa\u6211\u7684\u8f49\u9304\u55ce\uff1f\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"\\u003Cp>\u662f\u7684\uff01\u8f49\u9304\u6587\u4ef6\u53ef\u4ee5\u4e0b\u8f09\u70ba\u4ee5\u4e0b\u683c\u5f0f\uff1aPDF\u3001DOCX\u3001\u5b57\u5e55\uff08SRT/VTT\uff09\u3001CSV \u548c TXT\u3002\\u003C/p>\\n\\u003Cp>\u60a8\u4e5f\u53ef\u4ee5\u901a\u904e\\u003Ca href=\\\"https://turboscribe.ai/zh-TW/blog/export-and-manage-files-in-bulk\\\">\u6279\u91cf\u64cd\u4f5c\\u003C/a>\u540c\u6642\u532f\u51fa\u591a\u500b\u6587\u4ef6\u3002\\u003C/p>\\n\"}},{\"@type\":\"Question\",\"name\":\"\u60a8\u652f\u6301\u54ea\u4e9b\u8a9e\u8a00\uff1f\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"\\u003Cp>TurboScribe\u4f7f\u7528\u6700\u9ad8\u7cbe\u78ba\u5ea6\u7684AI\u8f49\u9304\u6280\u8853\u5c07\u8a9e\u97f3\u8f49\u63db\u70ba\u6587\u672c\uff0c\u652f\u6301\u8d85\u904e98\u7a2e\u8a9e\u8a00\u3002\\u003C/p>\\n\\u003Cp>\u50cf\u82f1\u8a9e\u9019\u6a23\u7684\u8a9e\u8a00\u662f\u6700\u6e96\u78ba\u7684\uff0c\u901a\u5e38\u5177\u6709\u8207\u4eba\u985e\u6c34\u5e73\u76f8\u7576\u7684\u8868\u73fe\uff0c\u4e26\u4e14\u80fd\u5920\u5f37\u529b\u8b58\u5225\u5c08\u696d\u3001\u9818\u57df\u7279\u5b9a\u7684\u8a5e\u5f59\u3002\u8a9e\u97f3\u8f49\u6587\u672c\u7684\u6e96\u78ba\u6027\u56e0\u8a9e\u8a00\u800c\u7570\u3002\u60a8\u5728\u4ee5\u4e0b\u8a9e\u8a00\u4e2d\u6703\u7372\u5f97\u6700\u4f73\u7d50\u679c\uff1a\u82f1\u8a9e\u3001\u897f\u73ed\u7259\u8a9e\u3001\u6cd5\u8a9e\u3001\u5fb7\u8a9e\u3001\u7fa9\u5927\u5229\u8a9e\u3001\u8461\u8404\u7259\u8a9e\u3001\u8377\u862d\u8a9e\u3001\u4e2d\u6587\u3001\u65e5\u8a9e\u3001\u4fc4\u8a9e\u3001\u963f\u62c9\u4f2f\u8a9e\u3001\u5370\u5730\u8a9e\u3001\u745e\u5178\u8a9e\u3001\u632a\u5a01\u8a9e\u3001\u4e39\u9ea5\u8a9e\u3001\u6ce2\u862d\u8a9e\u3001\u571f\u8033\u5176\u8a9e\u3001\u5e0c\u4f2f\u4f86\u8a9e\u3001\u5e0c\u81d8\u8a9e\u3001\u6377\u514b\u8a9e\u3001\u8d8a\u5357\u8a9e\u548c\u97d3\u8a9e\u3002\u5efa\u8b70\u60a8\u4f7f\u7528\u514d\u8cbb\u7248\u672c\u9032\u884c\u5be6\u9a57\u3002\\u003C/p>\\n\"}},{\"@type\":\"Question\",\"name\":\"\u53e3\u97f3\u3001\u80cc\u666f\u566a\u97f3\u548c\u7cdf\u7cd5\u7684\u97f3\u8cea\u600e\u9ebc\u8fa6\uff1f\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"\\u003Cp>\u96d6\u7136\u4e7e\u6de8\u4e14\u6e05\u6670\u7684\u97f3\u8a0a\u80fd\u7522\u751f\u6700\u4f73\u6548\u679c\uff0c\u4f46TurboScribe\u901a\u5e38\u5c0d\u53e3\u97f3\u3001\u80cc\u666f\u566a\u97f3\u548c\u8f03\u4f4e\u7684\u97f3\u8a0a\u8cea\u91cf\u8655\u7406\u5f97\u5f88\u597d\u3002\\u003C/p>\\n\\u003Cp>\u5982\u679c\u60a8\u6b63\u5728\u8f49\u9304\u97f3\u8a0a\u8cea\u91cf\u975e\u5e38\u5dee\u7684\u6587\u4ef6\uff0cTurboScribe\u6709\u5167\u5efa\u7684\u97f3\u8a0a\u6062\u5fa9\u5de5\u5177\u3002\u4e0a\u50b3\u6587\u4ef6\u6642\uff0c\u53ef\u4ee5\u901a\u904e\u300c\u66f4\u591a\u8a2d\u5b9a\u300d\u4e2d\u7684\u300c\u6062\u5fa9\u97f3\u8a0a\u300d\u9078\u9805\u4f86\u555f\u7528\u3002\u9019\u5229\u7528 AI \u53bb\u9664\u80cc\u666f\u566a\u97f3\u4e26\u589e\u5f37\u4eba\u8072\u3002\u97f3\u8a0a\u6062\u5fa9\u6bcf\u5c0f\u6642\u97f3\u8a0a/\u8996\u983b\u9700\u8981\u984d\u59162-3\u5206\u9418\u3002\\u003C/p>\\n\"}},{\"@type\":\"Question\",\"name\":\"\u5982\u4f55\u5728\u6211\u7684\u8f49\u9304\u4e2d\u6a19\u8a3b\u8aaa\u8a71\u8005\uff1f\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"\\u003Cp>\u4e0a\u50b3\u6587\u4ef6\u6642\uff0c\u53ef\u4ee5\u901a\u904e\u9078\u4e2d\u300c\u66f4\u591a\u8a2d\u5b9a\u300d\u4e0b\u7684\u300c\u8a9e\u8005\u8b58\u5225\u300d\u9078\u6846\u4f86\u555f\u7528\u8a9e\u8005\u8b58\u5225\u3002 \u9700\u8981\u984d\u5916\u4e00\u5169\u5206\u9418\uff08\u6bcf\u5c0f\u6642\u97f3\u8a0a\uff09\u4f86\u5275\u5efa\u5e36\u6709\u8aaa\u8a71\u8005\u6a19\u7c64\u7684\u8f49\u9304\u6587\u4ef6\u3002\\u003C/p>\\n\"}},{\"@type\":\"Question\",\"name\":\"\u6211\u53ef\u4ee5\u5c07\u8f49\u9304\u548c\u5b57\u5e55\u7ffb\u8b6f\u6210\u5176\u4ed6\u8a9e\u8a00\u55ce\uff1f\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"\\u003Cp>\u662f\u7684\uff01 \u60a8\u53ef\u4ee5\u5c07\u8f49\u9304\u6216\u5b57\u5e55\u7ffb\u8b6f\u6210\u8d85\u904e130\u7a2e\u8a9e\u8a00\u3002\u5728\u67e5\u770b\u4efb\u4f55\u8f49\u9304\u6642\u9ede\u64ca\u300c\u7ffb\u8b6f\u300d\u6309\u9215\u4ee5\u6253\u958b\u7ffb\u8b6f\u5de5\u5177\u3002\u7136\u5f8c\u9078\u64c7\u60a8\u60f3\u8981\u7684\u8a9e\u8a00\u548c\u6587\u4ef6\u683c\u5f0f\u4ee5\u4e0b\u8f09\u7ffb\u8b6f\u904e\u7684\u8f49\u9304\u6216\u5b57\u5e55\u3002\\u003C/p>\\n\\u003Cp>\u60a8\u4e5f\u53ef\u4ee5\u901a\u904e\u5728\u4e0a\u50b3\u6587\u4ef6\u6642\u9078\u64c7\u300c\u66f4\u591a\u8a2d\u5b9a\u300d\u4e0b\u7684\u300c\u8f49\u9304\u70ba\u82f1\u8a9e\u300d\uff0c\u5c07\u97f3\u983b\u6216\u8996\u983b\u6587\u4ef6\uff08\u4efb\u4f55\u8a9e\u8a00\uff09\u76f4\u63a5\u8f49\u9304\u70ba\u82f1\u8a9e\u3002\\u003C/p>\\n\"}},{\"@type\":\"Question\",\"name\":\"\u6211\u53ef\u4ee5\u8f49\u9304\u591a\u5c11\u5167\u5bb9\uff1f\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"\\u003Cp>\u6211\u5011\u6c92\u6709\u7e3d\u4f7f\u7528\u91cf\u4e0a\u9650\uff0c\u800c\u4e14\u6211\u5011\u7684\u7cfb\u7d71\u8a2d\u8a08\u662f\u70ba\u4e86\u8b93\u60a8\u6bcf\u6708\u81f3\u5c11\u80fd\u8f49\u9304720\u5c0f\u6642\u7684\u97f3\u8a0a\u6216\u8996\u983b\u3002\\u003C/p>\\n\\u003Cp>\u9019\u610f\u5473\u8457\u60a8\u53ef\u4ee5\u4f7f\u7528TurboScribe\u8f49\u9304\u60a8\u6574\u500b\u751f\u6d3b\uff08\u6bcf\u592924\u5c0f\u6642 x \u6bcf\u670830\u5929 = 720\u5c0f\u6642\uff0c\u621643,200\u5206\u9418\uff09\uff01\u6b63\u5982\u4e00\u4f4d\u5ba2\u6236\u8aaa\u7684\u90a3\u6a23\uff1a\u300c\u6211\u4e0d\u5047\u601d\u7d22\u5730\u8f49\u9304\u4e00\u5207\u3002\u300d\\u003C/p>\\n\\u003Cp>\u5982\u679c\u60a8\u8f49\u9304\u7684\u91cf\u975e\u5e38\u5927\uff08\u6bcf\u6708\u8d85\u904e720\u5c0f\u6642\uff0c\u6216\u4f7f\u7528\u91cf\u524d0.1%\uff09\uff0c\u6211\u5011\u64b0\u5beb\u4e86\u4e00\u500b\u6709\u7528\u7684\\u003Ca href=\\\"https://turboscribe.ai/zh-TW/help/tips-for-transcribing-extremely-large-volumes\\\">\u6307\u5357\\u003C/a>\u4f86\u5e6b\u52a9\u60a8\u5145\u5206\u5229\u7528TurboScribe\u3002\\u003C/p>\\n\"}},{\"@type\":\"Question\",\"name\":\"\u5982\u4f55\u53d6\u6d88\u6211\u7684\u8a02\u95b1\uff1f\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"\\u003Cp>\u60a8\u53ef\u4ee5\u96a8\u6642\u9ede\u64ca\u300c\u5e33\u6236\u8a2d\u5b9a\u300d\uff0c\u7136\u5f8c\u9078\u64c7\u300c\u7ba1\u7406\u8a02\u95b1\u300d\u4f86\u53d6\u6d88\u60a8\u7684\u8a02\u95b1\u3002\u5728\u7576\u524d\u8a08\u8cbb\u5468\u671f\u7d50\u675f\u4e4b\u524d\uff0c\u60a8\u5c07\u64c1\u6709\u5b8c\u6574\u7684TurboScribe\u8a2a\u554f\u6b0a\u9650\u3002\\u003C/p>\\n\"}},{\"@type\":\"Question\",\"name\":\"\u8ab0\u662fTurboScribe\u80cc\u5f8c\u7684\u5718\u968a\uff1f\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"\\u003Cp>\u55e8 \\u003Cimg src=\\\"/_content/thirdparty/cdn.jsdelivr.net/gh/svgmoji/svgmoji@3.2.0/packages/svgmoji__noto/svg/1F44B.svg\\\" alt=\\\"\ud83d\udc4b\\\" class=\\\"w-6 h-6 m-0 inline\\\"/> \u6211\u662fLeif\u3002\u6211\u5728Meta\u7b49\u516c\u53f8\u82b1\u4e86\u8fd1\u5341\u5e74\u6642\u9593\u5efa\u7acbAI\u7cfb\u7d71\u3002\u73fe\u5728\u6211\u6b63\u5728\u958b\u767c\u50cfTurboScribe\u9019\u6a23\u7684\u7522\u54c1\u548c\u670d\u52d9\u3002\\u003C/p>\\n\"}},{\"@type\":\"Question\",\"name\":\"\u6211\u9084\u6709\u5176\u4ed6\u554f\u984c\u3002\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"\\u003Cp>\u60a8\u53ef\u4ee5\u8a2a\u554f\u6211\u5011\u7684\\u003Ca href=\\\"https://turboscribe.ai/zh-TW/support\\\">\u5e6b\u52a9\u548c\u652f\u63f4\u4e2d\u5fc3\\u003C/a>\u4ee5\u67e5\u8a62\u6709\u95dc\u4f7f\u7528TurboScribe\u7684\u5e38\u898b\u554f\u984c\u7684\u7b54\u6848\u3002\\u003C/p>\\n\\u003Cp>\u60a8\u4e5f\u53ef\u4ee5\u5c07\u4efb\u4f55\u984d\u5916\u554f\u984c\u767c\u9001\u81f3\\u003Ca href=\\\"mailto:leif@turboscribe.ai\\\">leif@turboscribe.ai\\u003C/a>\uff0c\u6211\u6703\u76e1\u5feb\u56de\u8986\u60a8\u3002\\u003C/p>\\n\"}}]}"
    ],
    "meta_tags": {
        "viewport": "minimum-scale=1, initial-scale=1, width=device-width",
